    x('pelvis-wall-march','Väggmarsch med neutralt bäcken','Wall march with neutral pelvis','Hållning','Stående',['Bål','Höft','Bäcken'],['Ländrygg','Höfter'],['Bål','Balans','Hållning'],['Stå lätt lutad mot en vägg med revben över bäcken.','Lyft ett knä utan att svanka eller tippa bäckenet framåt.','Sänk kontrollerat och växla sida.'],['Stand lightly supported by a wall with the ribs stacked over the pelvis.','Lift one knee without arching or tipping the pelvis forward.','Lower with control and alternate sides.']),

    x('gait-foot-tripod','Fotens trepunktsstöd','Foot tripod stance','Gång & löpning','Stående',['Fötter','Fotled','Ben'],['Fötter','Fotleder'],['Fötter','Balans'],['Stå barfota på en säker, jämn yta.','Känn kontakt under hälen, stortåns bas och lilltåns bas utan att krampa.','Behåll tårna avslappnade och fördela vikten jämnt.'],['Stand barefoot on a safe, even surface.','Feel contact under the heel, base of the big toe, and base of the little toe without gripping.','Keep the toes relaxed and distribute weight evenly.']),
    x('gait-barefoot-march','Lugn barfotamarsch','Gentle barefoot march','Gång & löpning','Stående',['Fötter','Ben','Bål'],['Fötter','Fotleder','Höfter'],['Koordination','Balans','Fötter'],['Stå barfota på en säker yta och börja med små steg på stället.','Lyft ett knä lågt och sätt ner foten tyst under kroppen.','Växla lugnt och avbryt vid smärta i fot eller vad.'],['Stand barefoot on a safe surface and begin with small steps in place.','Lift one knee low and place the foot quietly beneath the body.','Alternate calmly and stop with foot or calf pain.']),
    x('gait-short-step','Korta mjuka gångsteg','Short quiet walking steps','Gång & löpning','Stående',['Fötter','Ben','Höft'],['Fötter','Fotleder','Knän'],['Koordination','Gångteknik'],['Gå långsamt på en ren, jämn yta.','Ta korta steg och låt foten landa nära under kroppen utan att tvinga ett visst fotisätt.','Håll stegen tysta och öka tiden gradvis.'],['Walk slowly on a clean, even surface.','Use short steps and let the foot land close beneath the body without forcing a particular strike.','Keep the steps quiet and increase time gradually.']),
    x('gait-run-prep','Barfota löpning på stället','Barefoot running-in-place preparation','Gång & löpning','Stående',['Fötter','Vader','Ben'],['Fötter','Fotleder','Vader'],['Koordination','Löpteknik'],['Börja med högst några sekunder på en säker yta.','Jogga mycket lätt på stället med korta, tysta kontakter och avslappnade anklar.','Sluta vid obehag och öka inte både tid och intensitet samtidigt.'],['Begin with only a few seconds on a safe surface.','Jog very lightly in place with short, quiet contacts and relaxed ankles.','Stop with discomfort and do not increase both time and intensity at once.']),

    x('oral-tongue-spot','Hitta tungans vilopunkt','Find the tongue resting spot','Ansiktsövningar','Sittande',['Tunga','Mun','Käke'],['Käkspänning'],['Ansiktskontroll','Avslappning'],['Sitt avslappnat med tänderna lätt isär.','Placera tungspetsen varsamt strax bakom de övre framtänderna, inte mot tänderna.','Låt resten av tungan vila lätt utan att pressa.'],['Sit relaxed with the teeth slightly apart.','Gently place the tongue tip just behind the upper front teeth, not against them.','Let the rest of the tongue rest lightly without pressing.']),
    x('oral-gentle-suction','Lätt tungkontakt mot gommen','Gentle tongue-to-palate contact','Ansiktsövningar','Sittande',['Tunga','Mun','Käke'],['Käkspänning'],['Ansiktskontroll'],['Fukta munnen och hitta tungans vilopunkt.','Låt tungan få en mycket lätt, jämn kontakt mot gommen.','Släpp direkt om käke, tänder eller tunga blir trötta; sug eller pressa inte hårt.'],['Moisten the mouth and find the tongue resting spot.','Allow very light, even contact between the tongue and palate.','Release if the jaw, teeth, or tongue tire; do not suck or press hard.']),
    x('oral-lip-seal','Avslappnad läppslutning','Relaxed lip seal','Ansiktsövningar','Sittande',['Läppar','Mun','Käke'],['Käkspänning'],['Avslappning','Ansiktskontroll'],['Slappna av i käke och axlar.','För läpparna mjukt ihop medan tänderna fortfarande är isär.','Behåll bara om näsandningen känns fri; forcera inte vid täppa.'],['Relax the jaw and shoulders.','Bring the lips gently together while the teeth remain apart.','Continue only if nasal breathing feels clear; do not force it with congestion.']),
    x('oral-nasal-check','Lugn kontroll av näsandning','Gentle nasal-breathing check','Ansiktsövningar','Sittande',['Näsa','Andning','Mun'],['Käkspänning'],['Andning','Avslappning'],['Sitt upprätt och andas normalt utan att ändra rytmen.','Stäng läpparna mjukt och prova ett lugnt andetag genom näsan.','Öppna munnen och avbryt om luftflödet känns blockerat, ansträngt eller obehagligt.'],['Sit upright and breathe normally without changing the rhythm.','Close the lips gently and try one calm breath through the nose.','Open the mouth and stop if airflow feels blocked, strained, or uncomfortable.']),

    x('breath-diaphragm','Lugn diafragmaandning','Calm diaphragmatic breathing','Andningsövningar','Ryggläge',['Andning','Bål','Avslappning'],['Stress','Spänning'],['Andning','Avslappning'],['Ligg bekvämt med en hand på bröstet och en på magen.','Andas lugnt så att den nedre handen rör sig mer än den övre.','Låt utandningen ske utan att pressa ut all luft.'],['Lie comfortably with one hand on the chest and one on the abdomen.','Breathe calmly so the lower hand moves more than the upper hand.','Let the exhale happen without forcing all the air out.']),
    x('breath-long-exhale','Lugn andning med längre utandning','Gentle longer-exhale breathing','Andningsövningar','Sittande',['Andning','Avslappning'],['Stress','Spänning'],['Andning','Avslappning'],['Andas in lugnt under en bekväm räkning.','Andas ut något längre, utan att tömma lungorna maximalt.','Återgå till normal andning vid yrsel, oro eller luftbrist.'],['Inhale calmly for a comfortable count.','Exhale a little longer without emptying the lungs completely.','Return to normal breathing with dizziness, anxiety, or air hunger.']),
    x('breath-equal','Jämn rytmandning','Equal-rhythm breathing','Andningsövningar','Sittande',['Andning','Fokus'],['Stress','Spänning'],['Andning','Fokuskontroll'],['Välj en kort och bekväm rytm, till exempel tre sekunder.','Andas in och ut lika länge utan pauser.','Fortsätt några varv och släpp räkningen om den skapar spänning.'],['Choose a short comfortable rhythm, such as three seconds.','Inhale and exhale for the same duration without holds.','Continue for a few rounds and drop the count if it creates tension.']),
    x('breath-hand-ribs','Andning mot nedre revben','Lower-rib breathing awareness','Andningsövningar','Sittande',['Andning','Bröstkorg','Bål'],['Stress','Övre rygg'],['Andning','Rörlighet'],['Placera händerna lätt runt de nedre revbenen.','Andas in och känn en liten rörelse åt sidorna och bakåt.','Andas ut mjukt och behåll axlarna avslappnade.'],['Place the hands lightly around the lower ribs.','Inhale and notice a small movement to the sides and back.','Exhale softly while keeping the shoulders relaxed.']),

    x('meditation-breath-count','Andningsräkning','Breath-counting meditation','Meditation','Sittande',['Fokus','Andning','Avslappning'],['Stress','Spänning'],['Fokuskontroll','Avslappning'],['Sitt bekvämt och låt andningen vara naturlig.','Räkna varje utandning från ett till fem.','Börja lugnt om från ett när tankarna vandrar.'],['Sit comfortably and let the breath remain natural.','Count each exhale from one to five.','Gently restart at one when the mind wanders.']),
    x('meditation-senses','Fem sinnen som ankare','Five-senses grounding','Meditation','Sittande',['Fokus','Sinnen','Avslappning'],['Stress','Spänning'],['Fokuskontroll','Avslappning'],['Lägg märke till några saker du kan se och höra.','Notera kontakt mot stol, golv eller kläder.','Avsluta med ett lugnt andetag och orientera dig i rummet.'],['Notice a few things you can see and hear.','Notice contact with the chair, floor, or clothing.','Finish with a calm breath and orient yourself to the room.']),
    x('meditation-open','Öppen uppmärksamhet','Open-awareness meditation','Meditation','Sittande',['Fokus','Avslappning'],['Stress','Spänning'],['Fokuskontroll','Avslappning'],['Sitt med mjuk blick eller slutna ögon om det känns tryggt.','Lägg märke till ljud, kroppskänslor och tankar utan att hålla fast vid dem.','Öppna ögonen och pausa om övningen känns överväldigande.'],['Sit with a soft gaze or closed eyes if that feels safe.','Notice sounds, body sensations, and thoughts without holding onto them.','Open the eyes and pause if the practice feels overwhelming.']),
    x('meditation-walking','Långsam gångmeditation','Slow walking meditation','Meditation','Stående',['Fokus','Fötter','Balans'],['Stress','Spänning'],['Fokuskontroll','Balans'],['Välj en fri och säker sträcka.','Gå långsamt och lägg märke till hur varje fot lyfter och landar.','Stanna, orientera dig och återgå till normal gång.'],['Choose a clear and safe path.','Walk slowly and notice how each foot lifts and lands.','Stop, orient yourself, and return to normal walking.'])
